// ── EDIT THIS CONFIG ONCE ─────────────────────────────────
const CONFIG = {
  BACKEND_URL: 'http://host.docker.internal:5001',
  AUTOMATION_API_KEY: 'paste-your-automation-api-key',
  fromEmail: 'hello@mediportbd.com',
  storeName: 'MediportBD',
  storeUrl: 'https://mediportbd.com',
  segment: 'vip',       // who gets the digest
  limit: 50,            // max customers per run
  recLimit: 4           // products per digest
};
// ──────────────────────────────────────────────────────────
return { json: { CONFIG } };

// One item per customer with purchase history; skip those without a seed product.
const c = $input.item.json;
const seedProductId = c.orderStats?.lastProductIds?.[0];
if (!seedProductId || !c.email) {
  return null;
}
return { json: { customerId: String(c._id), email: c.email, name: c.name, seedProductId } };

// Build the recommendation digest email.
const CONFIG = $('Setup').first().json.CONFIG;
const customer = $('Per Customer').item.json;
const _r = $input.item.json;
const recs = (((_r.data && _r.data.products) || _r.products) || []).slice(0, CONFIG.recLimit);
if (!recs.length || !customer) {
  return null;
}
const cards = recs.map((p) => `
  <td width="25%" align="center" style="padding:8px">
    ${p.image ? `<img src="${p.image}" width="120" alt="" style="border-radius:6px"/>` : ''}
    <div style="font-size:13px;margin-top:6px"><a href="${CONFIG.storeUrl}/product/${p.slug}" style="color:#0d6efd;text-decoration:none">${p.name}</a></div>
    <div style="font-weight:bold;margin-top:4px">৳${Number(p.price).toLocaleString()}</div>
  </td>`).join('');
const html = `
  <div style="font-family:Arial,sans-serif;max-width:600px;margin:auto">
    <h2>Picked for you, ${customer.name}</h2>
    <p>Based on what you and similar medical professionals buy:</p>
    <table width="100%" cellpadding="0" cellspacing="0"><tr>${cards}</tr></table>
    <p><a href="${CONFIG.storeUrl}" style="background:#0d6efd;color:#fff;padding:12px 28px;text-decoration:none;border-radius:6px;display:inline-block">Shop All Products</a></p>
    <p style="color:#888;font-size:12px">Weekly digest. Reply STOP to unsubscribe.</p>
  </div>`;
return { json: { email: customer.email, subject: `${CONFIG.storeName}: 4 picks for your practice this week`, html } };

// Backend wraps lists as {success,data:{customers:[...]}}; emit one item per customer.
const r = $input.first().json;
const list = (r.data && Array.isArray(r.data.customers)) ? r.data.customers : [];
if (!list.length) {
  console.log('[Flatten] no customers in response');
}
return list.map(c => ({ json: c }));
